module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire not_s0, not_s1;
    wire and0, and1, and2, and3;

    not u1(not_s0, sel[0]);
    not u2(not_s1, sel[1]);

    and u3(and0, in[0], not_s1, not_s0);
    and u4(and1, in[1], not_s1, sel[0]);
    and u5(and2, in[2], sel[1], not_s0);
    and u6(and3, in[3], sel[1], sel[0]);

    or u7(out, and0, and1, and2, and3);

endmodule

