module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire not_s0, not_s1;
wire and0, and1, and2, and3;

not not0(not_s0, sel[0]);
not not1(not_s1, sel[1]);

and and_gate0(and0, in[0], not_s1, not_s0);
and and_gate1(and1, in[1], not_s1, sel[0]);
and and_gate2(and2, in[2], sel[1], not_s0);
and and_gate3(and3, in[3], sel[1], sel[0]);

or or_gate(out, and0, and1, and2, and3);

endmodule

