module traffic_light (
    input clk, reset,
    output [2:0] light
);

    parameter RED_STATE = 2'b00;
    parameter YELLOW_STATE = 2'b01;
    parameter GREEN_STATE = 2'b10;

    parameter RED_TIME = 3'd4;
    parameter YELLOW_TIME = 3'd2;
    parameter GREEN_TIME = 3'd4;

    reg [1:0] current_state;
    reg [1:0] next_state;
    reg [2:0] counter;

    assign light[0] = (current_state == GREEN_STATE);
    assign light[1] = (current_state == YELLOW_STATE);
    assign light[2] = (current_state == RED_STATE);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= RED_STATE;
            counter <= 3'b0;
        end else begin
            current_state <= next_state;
            if (current_state != next_state) begin
                counter <= 3'b0;
            end else begin
                counter <= counter + 1'b1;
            end
        end
    end

    always @(*) begin
        case (current_state)
            RED_STATE: begin
                if (counter >= RED_TIME - 1'b1) begin
                    next_state = GREEN_STATE;
                end else begin
                    next_state = RED_STATE;
                end
            end
            GREEN_STATE: begin
                if (counter >= GREEN_TIME - 1'b1) begin
                    next_state = YELLOW_STATE;
                end else begin
                    next_state = GREEN_STATE;
                end
            end
            YELLOW_STATE: begin
                if (counter >= YELLOW_TIME - 1'b1) begin
                    next_state = RED_STATE;
                end else begin
                    next_state = YELLOW_STATE;
                end
            end
            default: begin
                next_state = RED_STATE;
            end
        endcase
    end

endmodule

