module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // State definitions
    parameter RED = 2'b00;
    parameter YELLOW = 2'b01;
    parameter GREEN = 2'b10;

    // State register
    reg [1:0] state_reg;
    reg [1:0] state_next;

    // Timer counter
    reg [31:0] timer;

    // Timer parameters (adjustable)
    parameter RED_TIME = 32'd10;
    parameter YELLOW_TIME = 32'd3;
    parameter GREEN_TIME = 32'd15;

    // State register sequential logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= RED;
            timer <= 32'd0;
        end else begin
            state_reg <= state_next;
            if (state_reg != state_next) begin
                timer <= 32'd0;
            end else begin
                timer <= timer + 32'd1;
            end
        end
    end

    // Next state logic
    always @(state_reg or timer) begin
        state_next = state_reg; // default: stay in current state

        case (state_reg)
            RED: begin
                if (timer >= RED_TIME - 1) begin
                    state_next = GREEN;
                end
            end
            GREEN: begin
                if (timer >= GREEN_TIME - 1) begin
                    state_next = YELLOW;
                end
            end
            YELLOW: begin
                if (timer >= YELLOW_TIME - 1) begin
                    state_next = RED;
                end
            end
            default: begin
                state_next = RED;
            end
        endcase
    end

    // Output logic - light[2:0] = {RED, YELLOW, GREEN}
    assign light = (state_reg == RED) ? 3'b100 :
                  (state_reg == YELLOW) ? 3'b010 :
                  (state_reg == GREEN) ? 3'b001 : 3'b100;

endmodule

