module int_sqrt (
    input signed [15:0] in_0,
    output signed [7:0] out
);

    reg signed [7:0] y;
    reg signed [15:0] x;
    reg [3:0] bit_index; // 8 bits -> need 4 iterations? Actually 7 bits magnitude (0..127) so 7 steps: 6 down to 0
    reg [2:0] state;
    reg signed [15:0] y2;
    reg signed [7:0] y_temp;

    localparam IDLE = 3'b000, COMPUTE = 3'b001, DONE = 3'b010;

    always @(in_0) begin
        if (in_0 < 0) begin
            y = 0;
        end else begin
            // start computation
            y_temp = 0;
            for (bit_index = 6; bit_index < 7; bit_index = bit_index - 1) begin // loop unroll manually
                y_temp = y_temp | (1 << bit_index);
                y2 = y_temp * y_temp;
                if (y2 > in_0) begin
                    y_temp = y_temp & ~(1 << bit_index);
                end
            end
            // repeat for bit 5
            y_temp = y_temp | (1 << 5);
            y2 = y_temp * y_temp;
            if (y2 > in_0) begin
                y_temp = y_temp & ~(1 << 5);
            end
            // bit 4
            y_temp = y_temp | (1 << 4);
            y2 = y_temp * y_temp;
            if (y2 > in_0) begin
                y_temp = y_temp & ~(1 << 4);
            end
            // bit 3
            y_temp = y_temp | (1 << 3);
            y2 = y_temp * y_temp;
            if (y2 > in_0) begin
                y_temp = y_temp & ~(1 << 3);
            end
            // bit 2
            y_temp = y_temp | (1 << 2);
            y2 = y_temp * y_temp;
            if (y2 > in_0) begin
                y_temp = y_temp & ~(1 << 2);
            end
            // bit 1
            y_temp = y_temp | (1 << 1);
            y2 = y_temp * y_temp;
            if (y2 > in_0) begin
                y_temp = y_temp & ~(1 << 1);
            end
            // bit 0
            y_temp = y_temp | (1 << 0);
            y2 = y_temp * y_temp;
            if (y2 > in_0) begin
                y_temp = y_temp & ~(1 << 0);
            end
            y = y_temp;
        end
    end

    assign out = y;

