module int_sqrt (
    input signed [15:0] in_0,
    output signed [7:0] out
);

    reg signed [7:0] y;
    reg signed [15:0] x;
    reg signed [15:0] low, high, mid, mid_sq;
    integer i;

    always @(*) begin
        x = in_0;
        if (x < 0) begin
            y = 0;
        end else begin
            low = 0;
            high = x;
            if (high > 255) high = 255; // since y is 8-bit signed, max positive is 127, but unsigned max would be 255; but here output is signed, so max y is 127 for x up to 32767.
            // Actually, 127^2 = 16129, 128^2=16384, so for x up to 32767, y max is 181 but 181^2=32761, but our output is signed 8-bit: max positive is 127, so we cap high at 127.
            if (high > 127) high = 127;
            y = 0;

            for (i = 0; i < 8; i = i + 1) begin
                mid = (low + high) / 2;
                mid_sq = mid * mid;
                if (mid_sq == x) begin
                    y = mid;
                    low = high; // force exit
                end else if (mid_sq < x) begin
                    low = mid + 1;
                    y = mid;
                end else begin
                    high = mid - 1;
                end
                if (low > high) i = 8; // terminate early
            end
        end
    end

    assign out = y;

endmodule

