    localparam IDLE = 3'b000,
               INIT = 3'b001,
               MULT = 3'b010,
               MOD  = 3'b011,
               DONE = 3'b100;

    always @(*) begin
        case (state)
            INIT: begin
                result = (in_2 != 0) ? in_0 % in_2 : in_0;
                counter = in_1 - 1;
                temp = result;
            end
            MULT: begin
                temp = result * in_0;
            end
            MOD: begin
                if (in_2 != 0) begin
                    result = temp % in_2;
                end else begin
                    result = temp[7:0];
                end
                counter = counter - 1;
            end
            DONE: begin
                out = result;
            end
            default: begin
                result = 0;
                temp = 0;
                counter = 0;
            end
        endcase
    end

    always @(state or counter) begin
        if (state == IDLE) begin
            state = INIT;
        end else if (state == INIT) begin
            if (in_1 == 0) begin
                result = 1;
                state = DONE;
            end else begin
                state = MULT;
            end
        end else if (state == MULT) begin
            state = MOD;
        end else if (state == MOD) begin
            if (counter == 0) begin
                state = DONE;
            end else begin
                state = MULT;
            end
        end
    end

    assign out = (state == DONE) ? result : 0;
endmodule

module mod_exp (
