    input signed [7:0] in_1,
    input signed [7:0] in_2,
    output signed [7:0] out
);
    reg signed [7:0] result;
    reg signed [15:0] temp;
    reg [7:0] counter;
    reg [2:0] state;

    localparam IDLE = 3'b000,
               INIT = 3'b001,
               MULTIPLY = 3'b010,
               MODULO = 3'b011,
               DONE = 3'b100;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            result <= 8'b0;
            temp <= 16'b0;
            counter <= 8'b0;
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= INIT;
                    end
                end

                INIT: begin
                    result <= 8'b1;
                    counter <= in_1;
                    state <= (in_1 == 8'b0) ? DONE : MULTIPLY;
                end

                MULTIPLY: begin
                    if (counter != 8'b0) begin
                        temp = result * in_0;
                        state <= MODULO;
                    end else begin
                        state <= DONE;
                    end
                end

                MODULO: begin
                    if (in_2 != 8'b0) begin
                        if (temp >= 16'sb0) begin
                            result <= temp % in_2;
                        end else begin
                            result <= -((-temp) % in_2);
                        end
                        counter <= counter - 8'b1;
                        state <= MULTIPLY;
                    end else begin
                        result <= 8'b0;
                        state <= DONE;
                    end
                end

                DONE: begin
                    state <= IDLE;
                end
            endcase
        end
    end

    assign out = (state == DONE) ? result : 8'b0;

endmodule

