    input signed [3:0] in_1,
    output signed [15:0] out
);
    reg signed [15:0] result;
    reg signed [15:0] base;
    reg [3:0] exp;
    reg neg_exp;
    integer i;

    assign out = result;

    always @(*) begin
        result = 16'sd1;
        base = {{8{in_0[7]}}, in_0}; // sign-extend to 16 bits
        exp = in_1;
        neg_exp = 0;

        if (in_1 < 0) begin
            neg_exp = 1;
            exp = -in_1; // work with positive exponent for loop
        end

        if (in_1 == 0) begin
            result = 16'sd1;
        end else if (in_0 == 0) begin
            if (in_1 > 0)
                result = 16'sd0;
            else
                result = 16'sd0; // 0 to negative power is undefined, here 0
        end else if (in_0 == 16'sd1) begin
            result = 16'sd1;
        end else if (in_0 == -16'sd1) begin
            if (neg_exp) 
                result = (in_1[0] == 1) ? -16'sd1 : 16'sd1; // (-1)^odd = -1
            else
                result = (in_1[0] == 1) ? -16'sd1 : 16'sd1;
        end else if (neg_exp) begin
            result = 16'sd0; // negative exponent with base not ±1 -> 0
        end else begin
            // positive exponent case, iterative multiplication
            result = 16'sd1;
            for (i = 0; i < exp; i = i + 1) begin
                result = result * base;
            end
        end
    end
