    assign c1_1 = pp0[1] & pp1[0];
    assign c1_2 = pp0[2] & pp1[1];
    assign c1_3 = pp0[3] & pp1[2];

    // Second level addition (sum1 + pp2 shifted left by 2)
    assign sum2[0] = sum1[0];
    assign sum2[1] = sum1[1];
    assign sum2[2] = sum1[2] ^ c1_1;
    assign sum2[3] = sum1[3] ^ (c1_2 ^ pp2[0]);
    assign sum2[4] = sum1[4] ^ (c1_3 ^ pp2[1]);
