module pipelined_adder (
    input clk, rst,
    input [15:0] a, b,
    output reg [15:0] out
);

    wire [7:0] sum_low;
    wire carry_low;
    reg [7:0] a_high_reg, b_high_reg;
    reg [7:0] sum_low_reg;
    reg carry_low_reg;
    wire [7:0] sum_high;

    // First stage: lower 8-bit adder
    adder_8bit adder_low (
        .a(a[7:0]),
        .b(b[7:0]),
        .cin(1'b0),
        .sum(sum_low),
        .cout(carry_low)
    );

    // Second stage: upper 8-bit adder
    adder_8bit adder_high (
        .a(a_high_reg),
        .b(b_high_reg),
        .cin(carry_low_reg),
        .sum(sum_high),
        .cout()
    );

    // Pipeline registers
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_high_reg <= 8'b0;
            b_high_reg <= 8'b0;
            sum_low_reg <= 8'b0;
            carry_low_reg <= 1'b0;
            out <= 16'b0;
        end else begin
            a_high_reg <= a[15:8];
            b_high_reg <= b[15:8];
            sum_low_reg <= sum_low;
            carry_low_reg <= carry_low;
            out <= {sum_high, sum_low_reg};
        end
    end

endmodule

