    output sum, cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

module pipelined_adder (
    input clk, rst,
    input [15:0] a, b,
    output reg [15:0] out
);

    wire [7:0] sum_lower;
    wire carry_lower;
    reg [7:0] a_upper_reg, b_upper_reg;
    reg [7:0] sum_lower_reg;
    reg carry_lower_reg;
    wire [7:0] sum_upper;

    // First stage: lower 8-bit addition
    adder_8bit lower_adder (
        .a(a[7:0]),
        .b(b[7:0]),
        .cin(1'b0),
        .sum(sum_lower),
        .cout(carry_lower)
    );

    // Second stage: upper 8-bit addition
    adder_8bit upper_adder (
        .a(a_upper_reg),
        .b(b_upper_reg),
        .cin(carry_lower_reg),
        .sum(sum_upper),
        .cout()
    );

    // Pipeline registers
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_upper_reg <= 8'b0;
            b_upper_reg <= 8'b0;
            sum_lower_reg <= 8'b0;
            carry_lower_reg <= 1'b0;
            out <= 16'b0;
        end else begin
            a_upper_reg <= a[15:8];
            b_upper_reg <= b[15:8];
            sum_lower_reg <= sum_lower;
            carry_lower_reg <= carry_lower;
            out <= {sum_upper, sum_lower_reg};
        end
    end

endmodule

