module pipelined_multiplier (
    input clk, rst,
    input [7:0] a, b,
    output reg [15:0] out
);

    // Stage 1 registers
    reg [7:0] a_stage1, b_stage1;
    reg [15:0] partial_products [7:0];

    // Stage 2 registers
    reg [15:0] sum_stage2_0, sum_stage2_1, sum_stage2_2, sum_stage2_3;
    reg [15:0] sum_stage2_4, sum_stage2_5, sum_stage2_6;

    // Stage 3 registers
    reg [15:0] sum_stage3_0, sum_stage3_1, sum_stage3_2;
    reg [15:0] sum_stage3_3;

    integer i;

    // Pipeline Stage 1: Generate partial products
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_stage1 <= 8'b0;
            b_stage1 <= 8'b0;
            for (i = 0; i < 8; i = i + 1) begin
                partial_products[i] <= 16'b0;
            end
        end else begin
            a_stage1 <= a;
            b_stage1 <= b;
            for (i = 0; i < 8; i = i + 1) begin
                partial_products[i] <= b_stage1[i] ? (a_stage1 << i) : 16'b0;
            end
        end
    end

    // Pipeline Stage 2: First level of addition (reduce 8 to 4 sums)
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sum_stage2_0 <= 16'b0;
            sum_stage2_1 <= 16'b0;
            sum_stage2_2 <= 16'b0;
            sum_stage2_3 <= 16'b0;
            sum_stage2_4 <= 16'b0;
            sum_stage2_5 <= 16'b0;
            sum_stage2_6 <= 16'b0;
        end else begin
            sum_stage2_0 <= partial_products[0] + partial_products[1];
            sum_stage2_1 <= partial_products[2] + partial_products[3];
            sum_stage2_2 <= partial_products[4] + partial_products[5];
            sum_stage2_3 <= partial_products[6] + partial_products[7];
            sum_stage2_4 <= sum_stage2_0 + sum_stage2_1;
            sum_stage2_5 <= sum_stage2_2 + sum_stage2_3;
            sum_stage2_6 <= sum_stage2_4 + sum_stage2_5;
        end
    end

    // Pipeline Stage 3: Final addition and output
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sum_stage3_0 <= 16'b0;
            sum_stage3_1 <= 16'b0;
            sum_stage3_2 <= 16'b0;
            sum_stage3_3 <= 16'b0;
            out <= 16'b0;
        end else begin
            sum_stage3_0 <= sum_stage2_0;
            sum_stage3_1 <= sum_stage2_1;
            sum_stage3_2 <= sum_stage2_2;
            sum_stage3_3 <= sum_stage2_3;
            out <= sum_stage2_6;
        end
    end

endmodule

module pipelined_multiplier (
    input clk, rst,
    input [7:0] a, b,
    output reg [15:0] out
);

    // Stage 1 registers
    reg [7:0] a_stage1, b_stage1;
    reg [15:0] partial_products [0:7];

    // Stage 2 registers
    reg [15:0] sum_stage2_0, sum_stage2_1, sum_stage2_2, sum_stage2_3;
    reg [15:0] sum_stage2_4, sum_stage2_5, sum_stage2_6;

    // Stage 3 registers
    reg [15:0] sum_stage3_0, sum_stage3_1, sum_stage3_2;
    reg [15:0] sum_stage3_3;

    integer i;

    // Pipeline Stage 1: Generate partial products
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_stage1 <= 8'b0;
            b_stage1 <= 8'b0;
            for (i = 0; i < 8; i = i + 1) begin
                partial_products[i] <= 16'b0;
            end
        end else begin
            a_stage1 <= a;
            b_stage1 <= b;

            for (i = 0; i < 8; i = i + 1) begin
                partial_products[i] <= b_stage1[i] ? (a_stage1 << i) : 16'b0;
            end
        end
    end

    // Pipeline Stage 2: First level of addition (reduce 8 to 4 sums)
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sum_stage2_0 <= 16'b0;
            sum_stage2_1 <= 16'b0;
            sum_stage2_2 <= 16'b0;
            sum_stage2_3 <= 16'b0;
            sum_stage2_4 <= 16'b0;
            sum_stage2_5 <= 16'b0;
            sum_stage2_6 <= 16'b0;
        end else begin
            sum_stage2_0 <= partial_products[0] + partial_products[1];
            sum_stage2_1 <= partial_products[2] + partial_products[3];
            sum_stage2_2 <= partial_products[4] + partial_products[5];
            sum_stage2_3 <= partial_products[6] + partial_products[7];

            // Second level of addition (reduce 4 to 2 sums)
            sum_stage2_4 <= sum_stage2_0 + sum_stage2_1;
            sum_stage2_5 <= sum_stage2_2 + sum_stage2_3;

            // Third level of addition (reduce 2 to 1 sum)
            sum_stage2_6 <= sum_stage2_4 + sum_stage2_5;
        end
    end

    // Pipeline Stage 3: Final output
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            out <= 16'b0;
        end else begin
            out <= sum_stage2_6;
        end
    end

endmodule

module pipelined_multiplier (
    input clk, rst,
    input [7:0] a, b,
    output reg [15:0] out
);

    // Stage 1: Partial products generation
    reg [7:0] a_stage1, b_stage1;
    reg [7:0] partial_products [7:0];

    // Stage 2: Intermediate accumulation
    reg [15:0] stage2_result;
    reg [7:0] a_stage2, b_stage2;

    // Stage 3: Final result
    reg [15:0] stage3_result;

    integer i;

    // Pipeline Stage 1: Generate partial products
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_stage1 <= 8'b0;
            b_stage1 <= 8'b0;
            for (i = 0; i < 8; i = i + 1) begin
                partial_products[i] <= 8'b0;
            end
        end else begin
            a_stage1 <= a;
            b_stage1 <= b;
            for (i = 0; i < 8; i = i + 1) begin
                partial_products[i] <= b[i] ? a : 8'b0;
            end
        end
    end

    // Pipeline Stage 2: Accumulate partial products
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            stage2_result <= 16'b0;
            a_stage2 <= 8'b0;
            b_stage2 <= 8'b0;
        end else begin
            a_stage2 <= a_stage1;
            b_stage2 <= b_stage1;
            stage2_result <= {8'b0, partial_products[0]} +
                            ({7'b0, partial_products[1], 1'b0}) +
                            ({6'b0, partial_products[2], 2'b0}) +
                            ({5'b0, partial_products[3], 3'b0}) +
                            ({4'b0, partial_products[4], 4'b0}) +
                            ({3'b0, partial_products[5], 5'b0}) +
                            ({2'b0, partial_products[6], 6'b0}) +
                            ({1'b0, partial_products[7], 7'b0});
        end
    end

    // Pipeline Stage 3: Final output
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            stage3_result <= 16'b0;
            out <= 16'b0;
        end else begin
            stage3_result <= stage2_result;
            out <= stage3_result;
        end
    end

endmodule

