            out <= 16'b0;
        end else begin
            sum_stage3_0 <= sum_stage2_0 + sum_stage2_1;
            sum_stage3_1 <= sum_stage2_2 + sum_stage2_3;
            sum_stage3_2 <= sum_stage2_4 + sum_stage2_5;
            sum_stage3_3 <= sum_stage2_6 + sum_stage2_7;
