module pipelined_multiplier (
    input clk, rst,
    input [7:0] a, b,
    output reg [15:0] out
);

    // Stage 1: Partial products
    reg [7:0] a_stage1, b_stage1;
    reg [63:0] partial_products;

    // Stage 2: Intermediate accumulation
    reg [7:0] a_stage2, b_stage2;
    reg [15:0] sum_stage2;

    // Stage 3: Final result
    reg [7:0] a_stage3, b_stage3;
    reg [15:0] sum_stage3;

    // Pipeline stage 1: Generate partial products
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_stage1 <= 8'b0;
            b_stage1 <= 8'b0;
            partial_products <= 64'b0;
        end else begin
            a_stage1 <= a;
            b_stage1 <= b;
            // Generate 64 partial products (8x8)
            partial_products[7:0]   <= b[0] ? a : 8'b0;
            partial_products[15:8]  <= b[1] ? a : 8'b0;
            partial_products[23:16] <= b[2] ? a : 8'b0;
            partial_products[31:24] <= b[3] ? a : 8'b0;
            partial_products[39:32] <= b[4] ? a : 8'b0;
            partial_products[47:40] <= b[5] ? a : 8'b0;
            partial_products[55:48] <= b[6] ? a : 8'b0;
            partial_products[63:56] <= b[7] ? a : 8'b0;
        end
    end

    // Pipeline stage 2: Accumulate partial products
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_stage2 <= 8'b0;
            b_stage2 <= 8'b0;
            sum_stage2 <= 16'b0;
        end else begin
            a_stage2 <= a_stage1;
            b_stage2 <= b_stage1;
            // Sum all partial products with proper shifting
            sum_stage2 <= {8'b0, partial_products[7:0]} +
                         ({7'b0, partial_products[15:8], 1'b0}) +
                         ({6'b0, partial_products[23:16], 2'b0}) +
                         ({5'b0, partial_products[31:24], 3'b0}) +
                         ({4'b0, partial_products[39:32], 4'b0}) +
                         ({3'b0, partial_products[47:40], 5'b0}) +
                         ({2'b0, partial_products[55:48], 6'b0}) +
                         ({1'b0, partial_products[63:56], 7'b0});
        end
    end

    // Pipeline stage 3: Final output
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_stage3 <= 8'b0;
            b_stage3 <= 8'b0;
            sum_stage3 <= 16'b0;
            out <= 16'b0;
        end else begin
            a_stage3 <= a_stage2;
            b_stage3 <= b_stage2;
            sum_stage3 <= sum_stage2;
            out <= sum_stage3;
        end
    end

endmodule

module pipelined_multiplier (
    input clk, rst,
    input [7:0] a, b,
    output reg [15:0] out
);

    // Pipeline stage registers
    reg [7:0] a_stage1, b_stage1;
    reg [15:0] partial_products [7:0];
    reg [15:0] stage2_reg [3:0];
    reg [15:0] stage3_reg [1:0];

    // Internal signals
    integer i;

    // Stage 1: Generate partial products
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            a_stage1 <= 8'b0;
            b_stage1 <= 8'b0;
            for (i = 0; i < 8; i = i + 1) begin
                partial_products[i] <= 16'b0;
            end
        end else begin
            a_stage1 <= a;
            b_stage1 <= b;
            for (i = 0; i < 8; i = i + 1) begin
                partial_products[i] <= b_stage1[i] ? (a_stage1 << i) : 16'b0;
            end
        end
    end

    // Stage 2: First level of addition (reduce 8 partial products to 4)
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 4; i = i + 1) begin
                stage2_reg[i] <= 16'b0;
            end
        end else begin
            stage2_reg[0] <= partial_products[0] + partial_products[1];
            stage2_reg[1] <= partial_products[2] + partial_products[3];
            stage2_reg[2] <= partial_products[4] + partial_products[5];
            stage2_reg[3] <= partial_products[6] + partial_products[7];
        end
    end

    // Stage 3: Second level of addition (reduce 4 to 2, then to final result)
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            stage3_reg[0] <= 16'b0;
            stage3_reg[1] <= 16'b0;
            out <= 16'b0;
        end else begin
            stage3_reg[0] <= stage2_reg[0] + stage2_reg[1];
            stage3_reg[1] <= stage2_reg[2] + stage2_reg[3];
            out <= stage3_reg[0] + stage3_reg[1];
        end
    end

endmodule

