    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 4; i = i + 1) begin
                stage2_reg[i] <= 16'b0;
            end
            a_stage2 <= 8'b0;
            b_stage2 <= 8'b0;
        end else begin
            a_stage2 <= a_stage1;
            b_stage2 <= b_stage1;
            stage2_reg[0] <= stage1_reg[0] + stage1_reg[1];
            stage2_reg[1] <= stage1_reg[2] + stage1_reg[3];
            stage2_reg[2] <= stage1_reg[4] + stage1_reg[5];
            stage2_reg[3] <= stage1_reg[6] + stage1_reg[7];
        end
    end

    // Pipeline Stage 3: Final addition and output
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 2; i = i + 1) begin
                stage3_reg[i] <= 16'b0;
