    reg [7:0] coeff [0:3];

    // Pipeline stage 1: Multiplication results
    reg [15:0] mult_stage [0:3];
    reg [7:0] x_delay1, x_delay2, x_delay3;

    // Pipeline stage 2: Partial sums
    reg [15:0] sum_stage1, sum_stage2;
    reg [7:0] x_delay4;

    // Initialize coefficients (example values - can be modified)
    initial begin
        coeff[0] = 8'h10;
        coeff[1] = 8'h20;
        coeff[2] = 8'h30;
        coeff[3] = 8'h40;
    end

    // Pipeline stage 1: Multiplications
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            mult_stage[0] <= 16'b0;
            mult_stage[1] <= 16'b0;
            mult_stage[2] <= 16'b0;
            mult_stage[3] <= 16'b0;
            x_delay1 <= 8'b0;
            x_delay2 <= 8'b0;
            x_delay3 <= 8'b0;
        end else begin
            // Current input multiplied with coefficients
            mult_stage[0] <= x * coeff[0];
            mult_stage[1] <= x_delay1 * coeff[1];
            mult_stage[2] <= x_delay2 * coeff[2];
            mult_stage[3] <= x_delay3 * coeff[3];

            // Delay line for input data
            x_delay1 <= x;
            x_delay2 <= x_delay1;
            x_delay3 <= x_delay2;
        end
    end

    // Pipeline stage 2: Partial sums
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sum_stage1 <= 16'b0;
            sum_stage2 <= 16'b0;
            x_delay4 <= 8'b0;
        end else begin
            // Sum pairs of multiplication results
            sum_stage1 <= mult_stage[0] + mult_stage[1];
            sum_stage2 <= mult_stage[2] + mult_stage[3];
            x_delay4 <= x_delay3;
        end
    end

    // Pipeline stage 3: Final sum and output
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y <= 16'b0;
        end else begin
