module pipelined_fir (
    input clk, rst,
    input [7:0] x,
    output reg [15:0] y
);

    // Coefficients for 4-tap FIR filter
    reg [7:0] coeff [0:3];
    initial begin
        coeff[0] = 8'h12;
        coeff[1] = 8'h34;
        coeff[2] = 8'h56;
        coeff[3] = 8'h78;
    end

    // Pipeline registers for input data (shift register)
    reg [7:0] x_delay [0:3];

    // Stage 1: Multiplication results
    reg [15:0] prod [0:3];

    // Stage 2: Partial sums
    reg [15:0] sum1, sum2;

    // Stage 3: Final sum
    reg [15:0] final_sum;

    // Input shift register and multiplication stage
    integer i;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 4; i = i + 1) begin
                x_delay[i] <= 8'b0;
                prod[i] <= 16'b0;
            end
        end else begin
            // Shift input data through delay line
            x_delay[0] <= x;
            for (i = 1; i < 4; i = i + 1) begin
                x_delay[i] <= x_delay[i-1];
            end

            // Perform multiplications
            for (i = 0; i < 4; i = i + 1) begin
                prod[i] <= x_delay[i] * coeff[i];
            end
        end
    end

    // Stage 2: Partial summation
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sum1 <= 16'b0;
            sum2 <= 16'b0;
        end else begin
            sum1 <= prod[0] + prod[1];
            sum2 <= prod[2] + prod[3];
        end
    end

    // Stage 3: Final output
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y <= 16'b0;
        end else begin
            y <= sum1 + sum2;
        end
    end

