            prod2 <= x_d2 * coeff2;
            prod3 <= x_d3 * coeff3;
        end
    end

    // Stage 2: Pipeline multiplication results and compute partial sums
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            prod0_d1 <= 16'b0;
            prod1_d1 <= 16'b0;
            prod2_d1 <= 16'b0;
            prod3_d1 <= 16'b0;
            prod0_d2 <= 16'b0;
            prod1_d2 <= 16'b0;
            prod2_d2 <= 16'b0;
            prod3_d2 <= 16'b0;

            sum01 <= 16'b0;
            sum23 <= 16'b0;
