            // Pipeline multiplication results
            prod0_d1 <= prod0;
            prod1_d1 <= prod1;
            prod2_d1 <= prod2;
            prod3_d1 <= prod3;

            prod0_d2 <= prod0_d1;
            prod1_d2 <= prod1_d1;
            prod2_d2 <= prod2_d1;
            prod3_d2 <= prod3_d1;

            // Compute partial sums
            sum01 <= prod0_d1 + prod1_d1;
            sum23 <= prod2_d1 + prod3_d1;
        end
    end

    // Stage 3: Final sum and output
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sum01_d1 <= 16'b0;
            sum23_d1 <= 16'b0;
            y <= 16'b0;
        end else begin
            // Pipeline partial sums
            sum01_d1 <= sum01;
            sum23_d1 <= sum23;

            // Final output
            y <= sum01_d1 + sum23_d1;
        end
    end

endmodule

