module compound_interest (
    input [15:0] P,
    input [7:0] r,
    input [7:0] n,
    output [31:0] A
);

    reg [31:0] base;
    reg [31:0] result;
    reg [7:0] counter;
    reg [31:0] temp_result;

    always @(*) begin
        base = {16'b0, 8'b10000000} + {24'b0, r};
        result = 32'b100000000000000000000000000000;

        if (n == 0) begin
            result = 32'b100000000000000000000000000000;
        end else begin
            temp_result = result;
            for (counter = 1; counter <= n; counter = counter + 1) begin
                temp_result = (temp_result * base) >> 7;
            end
            result = temp_result;
        end

        A = (P * result) >> 7;
    end

endmodule

module compound_interest (
    input [15:0] P,
    input [7:0] r,
    input [7:0] n,
    output [31:0] A
);

    // Internal signals
    reg [15:0] base;  // 1 + r in fixed-point (8.8 format)
    reg [31:0] accumulator;
    reg [31:0] temp_result;
    reg [7:0] counter;

    // Combinational logic for base calculation
    wire [15:0] base_comb;
    assign base_comb = 16'h0100 + {8'b0, r};  // 1.0 + r in fixed-point

    // Sequential logic for exponentiation
    always @(*) begin
        base = base_comb;
        accumulator = 32'h00010000;  // 1.0 in fixed-point (16.16 format)
        counter = n;

        if (n == 0) begin
            accumulator = 32'h00010000;  // (1+r)^0 = 1
        end else begin
            temp_result = {16'b0, base};
            while (counter > 1) begin
                temp_result = temp_result * base;
                temp_result = temp_result >> 8;  // Maintain fixed-point format
                counter = counter - 1;
            end
            accumulator = temp_result;
        end
    end

    // Final multiplication: P * (1+r)^n
    assign A = P * accumulator[31:16];  // Convert back to integer result

endmodule

module compound_interest (
