    output [7:0] wavelength  // wavelength in meters
);

    wire [15:0] c = 300;
    wire [15:0] div_result;

    assign div_result = (frequency == 8'b0) ? 16'b0 : c / frequency;
    assign wavelength = div_result[7:0];

endmodule

module wavelength (
    input [7:0] frequency,   // frequency in MHz
    output [7:0] wavelength  // wavelength in meters
);

    wire [15:0] div_result;
    wire zero_freq;

    assign zero_freq = (frequency == 8'b0);
    assign div_result = 300 / (zero_freq ? 8'b1 : frequency);
    assign wavelength = zero_freq ? 8'b0 : div_result[7:0];

endmodule

