module carbon_footprint (
    input [7:0] energy,
    input [7:0] distance,
    input [7:0] waste,
    output [15:0] footprint
);

    wire [15:0] energy_contrib;
    wire [15:0] distance_contrib;
    wire [15:0] waste_contrib;

    assign energy_contrib = energy * 11'd217;  // 0.85 * 256 = 217.6 ≈ 217
    assign distance_contrib = distance * 9'd51;  // 0.2 * 256 = 51.2 ≈ 51
    assign waste_contrib = waste * 8'd26;  // 0.1 * 256 = 25.6 ≈ 26

    assign footprint = energy_contrib + distance_contrib + waste_contrib;

endmodule

