module heat_index (
    input [7:0] temperature,   // Temperature in Celsius
    input [7:0] humidity,      // Humidity in percentage
    input signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9,    // Quartic T^2*R^2
    output signed [15:0] heat_index // Heat Index in Celsius
);

    // Convert inputs to signed for arithmetic operations
    wire signed [15:0] T_signed = {8'b0, temperature};
    wire signed [15:0] R_signed = {8'b0, humidity};

    // Intermediate terms
    wire signed [31:0] T2, R2, TR, T2R, TR2, T2R2;
    wire signed [31:0] term1, term2, term3, term4, term5, term6, term7, term8, term9;
    wire signed [31:0] sum_temp;

    // Calculate intermediate products
    assign T2 = T_signed * T_signed;
    assign R2 = R_signed * R_signed;
    assign TR = T_signed * R_signed;
    assign T2R = T2 * R_signed;
    assign TR2 = T_signed * R2;
    assign T2R2 = T2 * R2;

    // Calculate individual terms with coefficients
    assign term1 = C1 * T_signed;
    assign term2 = C2 * R_signed;
    assign term3 = C3 * TR;
    assign term4 = C4 * T2;
    assign term5 = C5 * R2;
    assign term6 = C6 * T2R;
    assign term7 = C7 * TR2;
    assign term8 = C8 * T2R2;
    assign term9 = C9;

    // Sum all terms
    assign sum_temp = term1 + term2 + term3 + term4 + term5 + term6 + term7 + term8 + term9;

    // Truncate to 16-bit output (take lower 16 bits)
    assign heat_index = sum_temp[15:0];

endmodule

module heat_index (
    input [7:0] temperature,   // Temperature in Celsius
    input [7:0] humidity,      // Humidity in percentage
    input signed [15:0] C1, C2, C3, C4, C5, C6, C7, C8, C9,    // Quartic T^2*R^2
    output signed [15:0] heat_index // Heat Index in Celsius
);

    // Internal signals for intermediate calculations
    wire signed [15:0] T, R;
    wire signed [31:0] T_sq, R_sq, T_R, T_sq_R, T_R_sq, T_sq_R_sq;
    wire signed [31:0] term1, term2, term3, term4, term5, term6, term7, term8, term9;
    wire signed [31:0] sum_temp;

    // Convert inputs to signed
    assign T = {8'b0, temperature};
    assign R = {8'b0, humidity};

    // Calculate intermediate products
    assign T_sq = T * T;
    assign R_sq = R * R;
    assign T_R = T * R;
    assign T_sq_R = T_sq * R;
    assign T_R_sq = T * R_sq;
    assign T_sq_R_sq = T_sq * R_sq;

    // Calculate individual terms
    assign term1 = C1 * T_R;
    assign term2 = C2 * T;
    assign term3 = C3 * R;
    assign term4 = C4 * T_sq;
    assign term5 = C5 * R_sq;
    assign term6 = C6 * T_sq_R;
    assign term7 = C7 * T_R_sq;
    assign term8 = C8 * T_sq_R_sq;
    assign term9 = C9;

    // Sum all terms
    assign sum_temp = term1 + term2 + term3 + term4 + term5 + term6 + term7 + term8 + term9;

    // Truncate to 16-bit output
    assign heat_index = sum_temp[31:16];

endmodule

