    output signed [15:0] heat_index // Heat Index in Celsius
);

    // Internal signals for intermediate calculations
    wire signed [15:0] T_signed, R_signed;
    wire signed [31:0] T2, R2, TR, T2R, TR2, T2R2;
    wire signed [31:0] term1, term2, term3, term4, term5, term6, term7, term8, term9;
    wire signed [31:0] sum_intermediate;

    // Convert inputs to signed
    assign T_signed = {8'b0, temperature};
    assign R_signed = {8'b0, humidity};

    // Calculate intermediate products
    assign T2 = T_signed * T_signed;
    assign R2 = R_signed * R_signed;
    assign TR = T_signed * R_signed;
    assign T2R = T2 * R_signed;
    assign TR2 = T_signed * R2;
    assign T2R2 = T2 * R2;

    // Calculate individual terms with coefficients
    assign term1 = C1 * T_signed;
    assign term2 = C2 * R_signed;
    assign term3 = C3 * TR;
    assign term4 = C4 * T2;
    assign term5 = C5 * R2;
    assign term6 = C6 * T2R;
    assign term7 = C7 * TR2;
    assign term8 = C8 * T2R2;
    assign term9 = C9;

    // Sum all terms
    assign sum_intermediate = term1 + term2 + term3 + term4 + term5 + term6 + term7 + term8 + term9;

    // Truncate to 16-bit output (take lower 16 bits)
    assign heat_index = sum_intermediate[15:0];

endmodule

module air_quality_index (
    input [7:0] pm2_5,
    input [7:0] pm10,
    input [7:0] no2,
    output [15:0] aqi
);

    wire [7:0] max_val;
    wire [7:0] min_val;
    wire [9:0] sum_val;
    wire [15:0] scaled_max;
    wire [15:0] scaled_min;
    wire [15:0] scaled_sum;

    // Find maximum value
    assign max_val = (pm2_5 >= pm10 && pm2_5 >= no2) ? pm2_5 :
                    (pm10 >= pm2_5 && pm10 >= no2) ? pm10 : no2;

    // Find minimum value
    assign min_val = (pm2_5 <= pm10 && pm2_5 <= no2) ? pm2_5 :
                    (pm10 <= pm2_5 && pm10 <= no2) ? pm10 : no2;

    // Calculate sum
    assign sum_val = pm2_5 + pm10 + no2;

    // Apply scaling factors (using integer approximations)
    // 0.5 * max_val = max_val / 2
    // 0.3 * min_val = (3 * min_val) / 10
    // 0.2 * sum_val = sum_val / 5
    assign scaled_max = {8'b0, max_val} * 16'd50 / 16'd100;
    assign scaled_min = {8'b0, min_val} * 16'd30 / 16'd100;
    assign scaled_sum = {6'b0, sum_val} * 16'd20 / 16'd100;

    // Calculate final AQI
    assign aqi = scaled_max + scaled_min + scaled_sum;

endmodule

