    wire [15:0] sum_temp1, sum_temp2, sum_temp3;
    wire [15:0] sum_temp4, sum_temp5, sum_temp6;

    // First level of addition
    assign sum_temp1 = r0 + r1;
    assign sum_temp2 = r2 + r3;
    assign sum_temp3 = r4 + r5;
    assign sum_temp4 = r6 + r7;

    // Second level of addition
